     "Para identificar la tasa de incumplimiento superior, el auditor puede usar esta tabla de evaluación de resultados; la tabla no proporciona tasas superiores de incumplimiento de la evaluación para todos los tamaños de la muestra posible, por tanto, el auditor puede usar el tamaño siguiente de la muestra más pequeño para identificar la tasa de incumplimiento superior."
