 "P-PC01-13": {
  "codigo": "P-PC01-13",
  "nombre": "Informe del Recontrol Integral Estatal",
  "pagina": 3606,
  "guia": {
   "titulo": "GUÍA PARA ELABORAR EL INFORME DEL RECONTROL INTEGRAL ESTATAL",
   "bloques": [
    [
     "subtitulo",
     "Propósito"
    ],
    [
     "parrafo",
     "Establecer los aspectos a considerar en el Informe del Recontrol Integral Estatal a presentar por el órgano u organismo controlador y el informe resumen que elabora la Contraloría General de la República."
    ],
    [
     "parrafo",
     "Elaboración y emisión"
    ],
    [
     "parrafo",
     "Elabora: controladores y Contraloría General de la República."
    ],
    [
     "parrafo",
     "Emisión: Contralor General de la República y jefe del sujeto controlado."
    ],
    [
     "parrafo",
     "El informe con los resultados del Control Integral Estatal se remite al Contralor General de República, mediante una carta, firmada por del jefe del órgano u organismo controlador."
    ],
    [
     "subtitulo",
     "Anotaciones"
    ],
    [
     "anotacion",
     "1",
     "Fecha de emisión."
    ],
    [
     "anotacion",
     "2",
     "Título del informe."
    ],
    [
     "anotacion",
     "3",
     "Introducción:"
    ],
    [
     "inciso",
     "a) Período de ejecución."
    ],
    [
     "inciso",
     "b) Nombre del controlado en el nivel que corresponda."
    ],
    [
     "inciso",
     "c) Nombres de los órganos u organismos controladores participantes."
    ],
    [
     "inciso",
     "d) Objetivos propuestos: redacción de los objetivos específicos propuestos y su cumplimiento."
    ],
    [
     "inciso",
     "e) Total de entidades visitadas: se cuantifica el total de visitas planificadas, el total real controlado y porciento de cumplimiento."
    ],
    [
     "inciso",
     "f) Total de acciones de control realizadas en el período de tres (3) meses antes del comienzo del Recontrol."
    ],
    [
     "inciso",
     "g) Detallar la cantidad de medidas evaluadas y de ellas las cumplidas, incumplidas, en proceso o en fecha."
    ],
    [
     "inciso",
     "h) Otros aspectos de interés que se considere necesario informar."
    ],
    [
     "anotacion",
     "4",
     "Conclusiones:"
    ],
    [
     "inciso",
     "a) En el caso de los informes de los órganos u organismos controladores: deben estar en correspondencia con los objetivos propuestos y contener el criterio del órgano u organismo controlado, de acuerdo con las categorías de avance, estancado y retroceso que se establecen en el procedimiento H-002-APC07 Control y Recontrol Integral Estatal."
    ],
    [
     "inciso",
     "b) En el caso del informe resumen que elabora la Contraloría General de la Republica: debe abordar en un párrafo inicial el criterio valorativo general dado al órgano, organismo de la Administración Central del Estado, entidad nacional, organización superior de dirección empresarial, la Administración Provincial, el Consejo de la Administración Municipal o entidad controlado en (avance, estancado o retroceso), así como los otorgados por los órganos u organismos controladores, que deben estar en correspondencia con los resultados obtenidos a partir de los objetivos propuestos para la ejecución del Recontrol."
    ],
    [
     "anotacion",
     "5",
     "Principales causas y condiciones identificadas que provocaron los incumplimientos más importantes detectados u otras deficiencias identificadas."
    ],
    [
     "anotacion",
     "6",
     "Resultados: cumplimiento del Plan de medidas y las medidas disciplinarias aplicadas derivadas del Control Integral Estatal. Para ello:"
    ],
    [
     "inciso",
     "a) Cuantificar y evaluar el cumplimiento del Plan de medidas y la efectividad alcanzada, para dar solución a las deficiencias o irregularidades detectadas. La Contraloría General de la República trabaja con el Plan de medidas general que le fue aprobado al órgano, organismo de la Administración Central del Estado, entidad nacional, organización superior de dirección empresarial, la Administración Provincial, el Consejo de la Administración Municipal o entidad controlado, considerando el número de orden de cada medida y relacionándolo con el de las entidades subordinadas cuando corresponda."
    ],
    [
     "inciso",
     "b) Cuantificar y evaluar el cumplimiento de las medidas disciplinarias aplicadas en correspondencia con las deficiencias detectadas y con la gravedad de los hechos, que se presenta en la plantilla P-PC01-12 Resumen de las medidas disciplinarias aplicadas."
    ],
    [
     "inciso",
     "c) Resumen del estado del Control interno asociado a los temas que fueron objeto de examen."
    ],
    [
     "inciso",
     "d) Valoración de la generalización de las medidas y su efectividad en los sistemas de Control interno."
    ],
    [
     "inciso",
     "e) Análisis del comportamiento del Plan de la Economía y el Presupuesto, correspondiente al período actual."
    ],
    [
     "anotacion",
     "7",
     "Recomendaciones."
    ],
    [
     "anotacion",
     "8",
     "Anexos:"
    ],
    [
     "inciso",
     "a) Cumplimiento del Plan de medidas general del órgano, organismo de la Administración Central del Estado, entidad nacional, organización superior de dirección empresarial, la Administración Provincial, el Consejo de la Administración Municipal o entidad controlado, que se muestra en la plantilla P- PC01-14 Cumplimiento del Plan de medidas general del controlado."
    ],
    [
     "inciso",
     "b) Cumplimiento del Plan de medidas por órgano u organismo controlador, que se muestra en la plantilla P-PC01-0 15 Cumplimiento del Plan de medidas por cada organismo controlador."
    ],
    [
     "inciso",
     "c) Identificación y cuantificación de daños y perjuicios económicos que se calcula de acuerdo con lo establecido en el procedimiento H-001-0002-01 Recolección de evidencia de la auditoría, para la identificación y cuantificación de daños y perjuicios económicos."
    ],
    [
     "anotacion",
     "9",
     "El informe resumen del Recontrol elaborado por la Contraloría General de la República, se envía al jefe del sujeto controlado, así como a las instancias del Estado, Gobierno y Partido Comunista de Cuba, según corresponda."
    ]
   ]
  },
  "formulario": null,
  "archivos": {
   "guia": "P-PC01-13 - Informe del Recontrol Integral Estatal - guia.docx"
  }
 },
